-- In-place match fields. Does not insert catalog rows or change compendium_collection.
BEGIN;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS foundry_pack_id text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS base_item text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS item_group text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS grade text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS material text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS remaster boolean;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS publication_license text;
ALTER TABLE pf2e_catalog_entries ADD COLUMN IF NOT EXISTS effect_origin text;
CREATE TEMP TABLE _doc (
  source_path text, foundry_type text, foundry_pack_id text, base_item text, item_group text,
  category text, grade text, material text, remaster boolean, publication_license text, effect_origin text,
  size text, hp integer, ac integer
) ON COMMIT DROP;

UPDATE pf2e_catalog_entries e SET
  foundry_type = d.foundry_type,
  foundry_pack_id = d.foundry_pack_id,
  base_item = d.base_item,
  item_group = d.item_group,
  category = COALESCE(d.category, e.category),
  grade = d.grade,
  material = d.material,
  remaster = d.remaster,
  publication_license = d.publication_license,
  effect_origin = d.effect_origin
FROM _doc d
WHERE e.ruleset_id = 'pf2e-remaster' AND e.compendium_collection IS NOT NULL AND e.source_path = d.source_path;
SELECT e.entry_id, e.foundry_document_id, COALESCE(e.pack_label, e.compendium_collection), e.rarity, d.size, d.hp, d.ac, COALESCE(e.source_url, ''), e.compendium_collection
FROM _doc d
JOIN pf2e_catalog_entries e ON e.ruleset_id = 'pf2e-remaster' AND e.source_path = d.source_path
WHERE d.foundry_type = 'npc' AND e.foundry_document_id IS NOT NULL
ON CONFLICT (entry_id) DO UPDATE SET size = EXCLUDED.size, hp = EXCLUDED.hp, ac = EXCLUDED.ac;
COMMIT;
